// src/utils/formatter.js
function singleLine(value) {
  return String(value ?? "").replace(/\s+/g, " ").trim();
}

// Split a markdown table row into trimmed cell texts. The leading and
// trailing pipes are optional; a row without any pipe yields one cell.
function splitTableRow(line) {
  let s = String(line ?? "").trim();
  if (s.startsWith("|")) s = s.slice(1);
  if (s.endsWith("|") && !s.endsWith("\\|")) s = s.slice(0, -1);
  return s.split("|").map((cell) => cell.trim());
}

// If `line` is a markdown table separator row (---, :---, ---:, :---:),
// return the per-column alignments ("left"/"center"/"right"/null);
// otherwise return null. The row must contain a pipe so a lone "---"
// stays a horizontal rule, never a one-column separator.
function tableSeparatorAlignments(line) {
  if (!String(line ?? "").includes("|")) return null;
  const cells = splitTableRow(line);
  if (!cells.length || !cells.every((c) => /^:?-+:?$/.test(c))) return null;
  return cells.map((c) => (c.startsWith(":") && c.endsWith(":") ? "center" : c.endsWith(":") ? "right" : c.startsWith(":") ? "left" : null));
}

// Safe inline DOM rendering: code spans first, labelled links before bare URLs.
// Emphasis: **bold** is tried before *italic*; a single * only opens when the
// next character is not a space or another *, and closes on a non-space, so
// arithmetic like "2 * 3" stays literal. _italic_ needs non-word boundaries
// on both sides so snake_case identifiers stay literal.
function appendSafeInline(node, text, depth=0) {
  if(depth>4) {node.appendChild(document.createTextNode(text));return;}
  const pattern=/(`[^`]+`|\*\*[^*]+\*\*|\*[^*\s](?:[^*]*[^*\s])?\*|(?<![\w])_[^_\s](?:[^_]*[^_\s])?_(?![\w])|\[[^\]\n]+\]\((?:https?:\/\/|mailto:)(?:[^\s<>"'()]|\([^\s<>"'()]*\))+(?:\s+"[^"\n]*")?\)|https?:\/\/[^\s<>"')\]]+)/gi;
  let index=0;
  for(const match of String(text).matchAll(pattern)) {
    node.appendChild(document.createTextNode(String(text).slice(index,match.index)));
    const part=match[0]; let child;
    if(part.startsWith('`')) {child=document.createElement('code');child.className='inline';child.textContent=part.slice(1,-1);}
    else if(part.startsWith('**')) {child=document.createElement('strong');appendSafeInline(child,part.slice(2,-2),depth+1);}
    else if(part.startsWith('*')) {child=document.createElement('em');appendSafeInline(child,part.slice(1,-1),depth+1);}
    else if(part.startsWith('_')) {child=document.createElement('em');appendSafeInline(child,part.slice(1,-1),depth+1);}
    else {
      const labelled=/^\[([^\]]+)\]\((.+)\)$/.exec(part);
      const href=labelled?labelled[2].replace(/\s+"[^"\n]*"$/,''):part;
      try {
        const url=new URL(href);
        if(!['http:','https:','mailto:'].includes(url.protocol))throw new Error('Unsafe URL');
        child=document.createElement('a');child.href=url.href;child.target='_blank';child.rel='noopener noreferrer';
        // Labels stay inert text; no HTML or nested links are executed.
        child.textContent=labelled?labelled[1]:part;
      }catch{child=document.createTextNode(part);}
    }
    node.appendChild(child);index=match.index+part.length;
  }
  node.appendChild(document.createTextNode(String(text).slice(index)));
}

